package cn.lili.modules.community.p0.stage3;
import cn.lili.modules.community.p0.support.*;import cn.lili.common.security.AuthUser;import cn.lili.common.security.session.*;import org.junit.jupiter.api.Test;import java.time.*;import java.util.*;import static cn.lili.modules.community.p0.support.Stage1Json.*;import static org.junit.jupiter.api.Assertions.*;import static org.mockito.Mockito.*;
class Stage3RecordsTest {
 static final String OP="S3_RECORD_ORIGINAL_001";
 static class Fixture {
  final Stage1Db db=mock(Stage1Db.class);final Stage1Context context=mock(Stage1Context.class);final Stage3Authorization auth=mock(Stage3Authorization.class);final Stage3Records service=new Stage3Records(db,context,auth);
  final Map<String,Object> row=map("id","10","order_id","11","store_id","12","point_id","14","actor_id","13","at_time",Instant.parse("2026-10-31T01:00:00Z"),"result","SUCCESS","credential_ref","abcdef0123456789","point_snapshot",write(map("id","14","name","成交点位")));
  final Map<String,Object> stored=map("orderId","11","verificationId","10","phase","COMPLETED","version",2,"completedAt","2026-10-31T01:00:00Z","manualCode","UNIT_SECRET_MUST_NOT_LEAK");
  Fixture(){var actor=new Stage1Context.Actor(new SessionIdentity("1",SessionDomain.MANAGER,"UNIT_MANAGER",null,null),AuthUser.builder().id("1").build(),"GET","/manager/p0/s3/verifications/10");when(context.require(SessionDomain.MANAGER)).thenReturn(actor);when(auth.managerPermissions("1")).thenReturn(Set.of("verification.read"));when(db.required(anyString(),any(Object[].class))).thenAnswer(i->{String sql=i.getArgument(0);if(sql.startsWith("SELECT v.*"))return row;if(sql.startsWith("SELECT operation_id"))return map("operation_id",OP,"operator_id","13","store_id","12","order_id","11");if(sql.startsWith("SELECT response_json"))return map("response_json",write(stored));throw new AssertionError("Unexpected query");});}
 }
 @Test void managerSeesOnlyMatchingOriginalPersistedReceiptAndExplicitSafeFields(){var f=new Fixture();var result=object(f.service.detail("10"));var original=result.getAsJsonObject("originalOperation");assertEquals(OP,original.get("operationId").getAsString());assertEquals("10",original.getAsJsonObject("result").get("verificationId").getAsString());assertEquals(2,original.getAsJsonObject("result").get("version").getAsInt());assertFalse(result.toString().contains("UNIT_SECRET_MUST_NOT_LEAK"));verify(f.db).required("SELECT response_json FROM li_p0_s3_operation WHERE identity_domain='STORE' AND actor_id=? AND store_scope=? AND operation_id=? AND action='verify' AND order_id=?","13","12",OP,"11");}
 @Test void mismatchedOriginalResultFailsClosedRatherThanInventingIdempotentSuccess(){var f=new Fixture();f.stored.put("verificationId","999");var error=assertThrows(Stage1Exception.class,()->f.service.detail("10"));assertEquals(503,error.status());assertEquals("ORIGINAL_VERIFICATION_RESULT_UNAVAILABLE",error.code());}
 @Test void rejectedAuditNeverAcquiresOrPretendsToHaveACompletionReceipt(){var f=new Fixture();f.row.put("result","REJECTED");assertFalse(object(f.service.detail("10")).has("originalOperation"));verify(f.db,never()).required(startsWith("SELECT response_json"),any(Object[].class));}
 @Test void currentManagerGrantIsRequiredBeforeReadingAnyRecord(){var f=new Fixture();when(f.auth.managerPermissions("1")).thenReturn(Set.of());assertEquals(403,assertThrows(Stage1Exception.class,()->f.service.detail("10")).status());verifyNoInteractions(f.db);}
 @Test void successfulDetailKeepsHistoricalPointNameWhenCurrentPointIsRenamed(){var f=new Fixture();f.row.put("point_name","当前已改名点位");var before=object(f.service.detail("10"));assertEquals("成交点位",before.get("pointName").getAsString());f.row.put("point_name","再次修改当前点位");assertEquals(before,object(f.service.detail("10")));}
 @Test void successfulListUsesTheSameHistoricalPointNameAsDetail(){var f=new Fixture();f.row.put("point_name","当前已改名点位");when(f.db.count(anyString(),any(Object[].class))).thenReturn(1L);when(f.db.rows(startsWith("SELECT v.*"),any(Object[].class))).thenReturn(List.of(f.row));var listed=object(f.service.list(Map.of())).getAsJsonArray("records").get(0).getAsJsonObject();assertEquals("成交点位",listed.get("pointName").getAsString());assertEquals(object(f.service.detail("10")).get("point"),listed.get("point"));}
 @Test void rejectedAuditWithoutSnapshotStillHasItsCurrentPointReference(){var f=new Fixture();f.row.put("result","REJECTED");f.row.put("point_snapshot",null);f.row.put("point_name","当前审计点位");var result=object(f.service.detail("10"));assertEquals("当前审计点位",result.get("pointName").getAsString());assertTrue(result.get("point").isJsonNull());assertFalse(result.has("originalOperation"));}
}